input.sparql:
SELECT ?zone ?zoneName ?ts WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?zoneName .
  ?s brick:hasProperty ?p .
  ?p brick:hasValue ?v .
}

SELECT ?sensor ?sensorLabel ?zone ?zoneLabel WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL { ?sensor rdfs:label ?sensorLabel }
  ?zone brick:hasSensor ?sensor .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  ?sensor ref:hasTimeseriesId ?tsid .
  BIND(?tsid AS ?zone) # placeholder
}

SELECT ?sensor ?sensorLabel ?zone ?zoneLabel ?tsid WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL { ?sensor rdfs:label ?sensorLabel }
  ?zone brick:hasSensor ?sensor .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  ?sensor ref:hasTimeseriesId ?tsid .
}

SELECT ?sensor ?sensorLabel WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL { ?sensor rdfs:label ?sensorLabel }
}

SELECT ?zone ?zoneLabel ?sensor ?tsid WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  ?zone brick:hasSensor ?sensor .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
}

SELECT ?zone ?zoneLabel ?sensor ?sensorLabel ?tsid WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  ?zone brick:hasPoint ?sensor .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  OPTIONAL { ?sensor rdfs:label ?sensorLabel }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
}
